1	import { all, get, run } from '../db/index.js';
2	
3	export interface User {
4	  id: number;
5	  username: string;
6	  display_name: string;
7	  created_at: string;
8	}
9	
10	export function getAllUsers(): User[] {
11	  return all('SELECT * FROM users ORDER BY display_name') as unknown as User[];
12	}
13	
14	export function getUserById(id: number): User | undefined {
15	  return get('SELECT * FROM users WHERE id = ?', [id]) as unknown as User | undefined;
16	}
17	
18	export function getUserByUsername(username: string): User | undefined {
19	  return get('SELECT * FROM users WHERE username = ?', [username]) as unknown as User | undefined;
20	}
21	
22	export function createUser(username: string, displayName: string): User {
23	  const result = run('INSERT INTO users (username, display_name) VALUES (?, ?)', [username, displayName]);
24	  return getUserById(result.lastInsertRowid)!;
25	}
26	
27	export function updateUser(id: number, data: { username?: string; displayName?: string }): User | undefined {
28	  const existing = getUserById(id);
29	  if (!existing) return undefined;
30	
31	  const updates: string[] = [];
32	  const values: unknown[] = [];
33	
34	  if (data.username !== undefined) {
35	    updates.push('username = ?');
36	    values.push(data.username);
37	  }
38	  if (data.displayName !== undefined) {
39	    updates.push('display_name = ?');
40	    values.push(data.displayName);
41	  }
42	
43	  if (updates.length === 0) return existing;
44	
45	  values.push(id);
46	  run(`UPDATE users SET ${updates.join(', ')} WHERE id = ?`, values);
47	  return getUserById(id);
48	}
49	
50	export function deleteUser(id: number): boolean {
51	  const result = run('DELETE FROM users WHERE id = ?', [id]);
52	  return result.changes > 0;
53	}
